import { UserMenu } from '@refy-design/web';
import type { ComponentProps } from 'react';
const user = { name: 'João Mendes', email: 'joao@example.com', initials: 'JM' };
export function Example() {
  const args: Pick<ComponentProps<typeof UserMenu>, 'user' | 'align' | 'entries'> = {
    user,
    align: 'start',
    entries: [
      { id: 'profile', label: 'Profile' },
      { id: 'billing', label: 'Billing' },
      { id: 'team', label: 'Team' },
      { type: 'separator' },
      { id: 'logout', label: 'Sign out', danger: true },
    ],
  };
  return <UserMenu {...args} />;
}

import { Button } from '@refy-design/web';
import { Drawer } from '@refy-design/web';
import { Input } from '@refy-design/web';
import { Switch } from '@refy-design/web';
import { UserMenu } from '@refy-design/web';
import { useState } from 'react';
const stack = { display: 'grid', gap: 'var(--space-4)', minWidth: 0 } as const;
function UserMenuExample() {
  const [panel, setPanel] = useState(''),
    [name, setName] = useState('João Mendes'),
    [draft, setDraft] = useState(name),
    [signedIn, setSignedIn] = useState(true),
    [notifications, setNotifications] = useState(true);
  return (
    <div style={stack}>
      {signedIn ? (
        <UserMenu
          user={{ name, email: 'joao@example.com', initials: 'JM' }}
          onSelect={(id) => {
            if (id === 'logout') setSignedIn(false);
            else {
              setDraft(name);
              setPanel(id);
            }
          }}
        />
      ) : (
        <>
          <p role="status">You signed out of the sample session.</p>
          <Button onClick={() => setSignedIn(true)}>Sign in again</Button>
        </>
      )}
      <Drawer
        open={Boolean(panel)}
        onOpenChange={(open) => {
          if (!open) setPanel('');
        }}
        title={panel === 'profile' ? 'Profile' : 'Account settings'}
      >
        <form
          style={stack}
          onSubmit={(e) => {
            e.preventDefault();
            setName(draft);
            setPanel('');
          }}
        >
          <Input
            label="Name"
            required
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
          />
          <Switch
            label="Get notifications"
            checked={notifications}
            onChange={(e) => setNotifications(e.target.checked)}
          />
          <Button type="submit">Save profile</Button>
        </form>
      </Drawer>
    </div>
  );
}
export function Example() {
  return <UserMenuExample />;
}
